/* Instalador de ZunzunOS en disco */
#include "z.h"
static zwin *W; static zdisk D[16]; static int nd, sel = -1, pct = -1, done; static char sysd[16], msgs[120], HM[16][16], HD[16][16];
static void load(void) { zdisk t[16]; int n = z_disks(t, 16); nd = 0; dk_sys_disk(sysd); for (int i = 0; i < n; i++) if (strcmp(t[i].name, sysd) && !!strncmp(t[i].name, "cd", 2) && t[i].ssize == 512) D[nd++] = t[i]; if (sel >= nd) sel = -1; zmount m[32]; int nm = z_mounts(m, 32); for (int i = 0; i < nd; i++) { HM[i][0] = 0; for (int k = 0; k < nm; k++) if (!strncmp(m[k].dev, D[i].name, strlen(D[i].name)) && strncmp(m[k].fstype, "fat", 3) == 0) { char q[80]; zdirent st; snprintf(q, 80, "/%s/ZUNZUN/KERNEL.BIN", m[k].name); if (!z_stat(q, &st)) { strncpy0(HM[i], m[k].name, 16); strncpy0(HD[i], m[k].dev, 16); } } } if (sel < 0) for (int i = 0; i < nd; i++) if (!D[i].removable) { sel = i; break; } }
static void draw(void) {
    g_clear(W, UI_BG); g_grad(W, 0, 0, W->w, 54, 0x0F766E, 0x115E59); g_text2(W, 16, 11, "Instalar ZunzunOS", 0xFFFFFF, 2); int y = 68; char b[140];
    g_text(W, 18, y, sel >= 0 && HM[sel][0] ? "Ya tiene ZunzunOS: Actualizar conserva tus datos; Instalar lo borra todo." : "Elige el disco. TODO su contenido se borrara.", UI_TEXT); y += 24; if (!nd) g_text(W, 18, y, "No hay ningun disco disponible.", 0xB91C1C);
    for (int i = 0; i < nd; i++) { zpart p[16]; int np = z_parts(D[i].name, p, 16); u64 mb = D[i].sectors >> 11; snprintf(b, 140, _("%s   %lu.%lu GB   %s   (%d particiones)"), D[i].name, mb >> 10, (mb & 1023) * 10 / 1024, D[i].model, np); if (HM[i][0]) { strcat(b, "  - "); strcat(b, _("ZunzunOS instalado")); } ui_button(W, 18, y, W->w - 36, 32, b, sel == i ? 2 : 0); y += 36; }
    int by = W->h - 46; if (pct >= 0) { g_rect(W, 18, by - 34, W->w - 36, 12, UI_LINE); g_rect(W, 18, by - 34, (W->w - 36) * pct / 100, 12, UI_ACC); } g_text(W, 18, by - 16, msgs, UI_TEXT); if (done) ui_button(W, W->w - 150, by, 132, 32, "Reiniciar", 2); else { ui_button(W, W->w - 150, by, 132, 32, "Instalar", sel >= 0 ? 2 : 0); if (sel >= 0 && HM[sel][0]) ui_button(W, W->w - 416, by, 260, 32, "Actualizar (conserva tus datos)", 2); } zw_present(W);
}
static void prog(int p, const char *m) { pct = p; strncpy0(msgs, m, 120); draw(); }
static void update(void) {
    if (sel < 0 || !HM[sel][0]) return; char q[200]; snprintf(q, 200, "%s /%s (%s)? %s", _("¿Actualizar ZunzunOS en"), HM[sel], D[sel].name, _("Tus documentos y ajustes se conservan.")); if (!ui_confirm("Actualizar", q)) return;
    int e = dk_update_system(HM[sel], HD[sel], "/rd/inst/KERNEL.BIN", "/rd/inst/INITRD.BIN", "/rd/inst/BOOTX64.EFI", "/rd/inst/boot.bin", prog); z_sync(); char m[100]; snprintf(m, 100, "[prueba] actualizacion en %s: %s", HD[sel], e ? z_errstr(e) : "OK"); z_log(m);
    if (e) { pct = -1; snprintf(msgs, 120, "Error: %s", z_errstr(e)); } else { done = 1; strcpy(msgs, _("Sistema actualizado. Retira la memoria USB y reinicia.")); } }
static void go(void) {
    if (sel < 0) return; zdisk *d = &D[sel]; char q[160], c[16] = ""; snprintf(q, 160, _("Se borrara TODO %s (%s). Escribe BORRAR:"), d->name, d->model); if (!ui_prompt("Confirmar instalacion", q, c, 16) || strcmp(c, _("BORRAR"))) { strcpy(msgs, _("Instalacion cancelada")); return; }
    int e = dk_install(d->name, d->sectors, d->ssize, prog); char m[100]; snprintf(m, 100, "[prueba] instalacion en %s: %s", d->name, e ? z_errstr(e) : "OK"); z_log(m); if (e) { pct = -1; snprintf(msgs, 120, _("Error: %s. El disco puede haber quedado incompleto."), z_errstr(e)); } else { done = 1; strcpy(msgs, _("Listo. Retira la memoria USB y reinicia.")); }
}
int main(const char *a) { W = zw_new("Instalar", -1, 0, 620, 400, WF_DECOR); load(); draw(); zevent e; for (;;) { if (!z_event(&e, 3000)) { if (pct < 0 && !done) { load(); draw(); } continue; } if (e.type == EV_REDRAW) { draw(); continue; } if (e.win != (u32)W->id) continue; if (e.type == EV_CLOSE) return 0; if (e.type == EV_DOWN) { int by = W->h - 46; if (e.y >= by && e.x >= W->w - 150) { if (done) z_reboot(); else go(); } else if (e.y >= by && e.x >= W->w - 416 && e.x < W->w - 156 && !done && sel >= 0 && HM[sel][0]) update(); else if (e.y >= 92 && !done) { int i = (e.y - 92) / 36; if (i < nd) sel = i; } draw(); } } }
